"""Campaign census: lease roles, causal application state and request activity.

For every query the visible ledger is reconciled, discovery roles (internal /
external) are derived per lease from live ICMP evidence, lease state priority
(``inactive`` > ``alias`` > ``conflict`` > ``usable``) is applied, and only then
is application causality assessed: a live application row is eligible when its
lease is usable, its target sits in a clean role and that role's earliest causal
witness is not later than the row's event.
"""
from common import addresses
from ledger import Ledger


def roles(icmp_rows):
    """Raw discovery evidence per lease: ``{lease: [internal, external, alias]}``.

    ``internal``/``external`` map a responder address to the earliest live event
    supporting that (role, address); the alias flag marks a lease whose canary
    produced a positive self echo.
    """
    found = {}
    for content in icmp_rows:
        _, lease, event, probe, target, responder, result = content
        bucket = found.get(lease)
        if bucket is None:
            bucket = found[lease] = [{}, {}, False]
        if probe[-2:] == '/c':
            # A positive self echo on any canary aliases the whole lease; any
            # other canary response contributes neither role.
            if result == 'echo' and responder == target:
                bucket[2] = True
            continue
        if result == 'timeout':
            continue
        if responder == target:
            if result != 'echo':
                # A self error is not a positive self echo.
                continue
            seen = bucket[0]
            witness = seen.get(target)
            if witness is None or event < witness:
                seen[target] = event
        else:
            seen = bucket[1]
            witness = seen.get(responder)
            if witness is None or event < witness:
                seen[responder] = event
    return found


def application_state(app_rows, states):
    """Causal census of live application rows.

    Returns ``(unbound, status, buckets)`` where ``status`` maps an eligible
    ``(lease, target, service)`` to ``open``/``closed`` (absent means unknown)
    and ``buckets`` maps ``(lease, service)`` to
    ``[internal_open, internal_closed, external_open, external_closed, errors]``.
    """
    groups = {}
    unbound = 0
    for content in app_rows:
        _, lease, event, target, service, attempt, result, _payload, parsed = content
        state = states[lease]
        if state[0] != 'usable':
            unbound += 1
            continue
        internal = state[1]
        witness = internal.get(target)
        if witness is None:
            external = state[2]
            witness = external.get(target)
            if witness is None:
                unbound += 1
                continue
            role = 2
        else:
            role = 0
        if witness > event:
            unbound += 1
            continue
        key = (lease, target, service)
        group = groups.get(key)
        if group is None:
            groups[key] = [attempt, role, [(result, parsed)]]
        elif attempt > group[0]:
            group[0] = attempt
            group[2] = [(result, parsed)]
        elif attempt == group[0]:
            group[2].append((result, parsed))
    status = {}
    buckets = {}
    for key, group in groups.items():
        rows = group[2]
        errors = 0
        decided = None
        closed = True
        opened = True
        signatures = set()
        for result, parsed in rows:
            if result == 'open':
                closed = False
                if parsed is None:
                    errors += 1
                    opened = False
                else:
                    signatures.add(parsed)
            else:
                opened = False
                if result != 'closed':
                    closed = False
        if closed:
            decided = 'closed'
        elif opened and len(signatures) == 1:
            decided = 'open'
        if decided is not None:
            status[key] = decided
        bucket = buckets.get((key[0], key[2]))
        if bucket is None:
            bucket = buckets[(key[0], key[2])] = [set(), set(), set(), set(), 0]
        bucket[4] += errors
        if decided is not None:
            bucket[group[1] + (0 if decided == 'open' else 1)].add(key[1])
    return unbound, status, buckets


def build(context, records, lows):
    """Snapshot reports for every query plus frozen request activity flags."""
    leases = context['leases']
    requests = context['requests']
    lease_order = sorted(leases)
    service_order = sorted(context['services'])
    planned = {lease: set(targets) for lease, targets in lows.items()}
    waiting = {}
    for name, row in requests.items():
        waiting.setdefault(row['at'], []).append(name)
    ledger = Ledger(records)
    snapshots = []
    active = {}
    for moment in context['queries']:
        ledger.advance(moment)
        counts, icmp_rows, app_rows = ledger.visible()
        found = roles(icmp_rows)
        states = {}
        for lease in lease_order:
            row = leases[lease]
            if moment < row['start'] or moment >= row['end']:
                states[lease] = ('inactive', {}, {}, [])
                continue
            evidence = found.get(lease)
            if evidence is None:
                internal = {}
                external = {}
                aliased = False
            else:
                internal, external, aliased = evidence
            conflicts = sorted(set(internal) & set(external))
            if aliased:
                state = 'alias'
            elif conflicts:
                state = 'conflict'
            else:
                state = 'usable'
            if state == 'usable':
                clean_internal = internal
                clean_external = external
            else:
                clean_internal = {}
                clean_external = {}
            states[lease] = (state, clean_internal, clean_external, conflicts)
        unbound, status, buckets = application_state(app_rows, states)
        reports = []
        for lease in lease_order:
            state, clean_internal, clean_external, conflicts = states[lease]
            if state == 'inactive':
                unresolved = []
            else:
                unresolved = sorted(planned[lease] - set(clean_internal) - set(clean_external))
            services = []
            for service in service_order:
                bucket = buckets.get((lease, service))
                if bucket is None:
                    services.append({'id': service, 'internal_open': [],
                                     'internal_closed': [], 'external_open': [],
                                     'external_closed': [], 'internal_only': [],
                                     'protocol_errors': 0})
                    continue
                internal_open = addresses(bucket[0])
                internal_closed = addresses(bucket[1])
                external_open = addresses(bucket[2])
                external_closed = addresses(bucket[3])
                if clean_external and len(bucket[3]) == len(clean_external):
                    internal_only = internal_open
                else:
                    internal_only = []
                services.append({'id': service, 'internal_open': internal_open,
                                 'internal_closed': internal_closed,
                                 'external_open': external_open,
                                 'external_closed': external_closed,
                                 'internal_only': internal_only,
                                 'protocol_errors': bucket[4]})
            reports.append({'lease': lease, 'state': state,
                            'conflicts': addresses(conflicts),
                            'internal': addresses(clean_internal),
                            'external': addresses(clean_external),
                            'unresolved': addresses(unresolved),
                            'services': services})
        snapshots.append({'at': moment,
                          'ledger': {'live': counts[0], 'deleted': counts[1],
                                     'conflict': counts[2]},
                          'unbound_applications': unbound,
                          'leases': reports})
        for name in waiting.get(moment, ()):
            row = requests[name]
            lease = row['lease']
            target = row['address']
            service = row['service']
            active[name] = (target in states[lease][1]
                            and status.get((lease, target, service)) is None)
    return snapshots, active
